// ===========================================================================
//  DSA paged-MQA gated top-k logits (issue #51, the kpool>1 indexer path).
//  Hand-checked cases, an independent reference (t-outer iteration, a
//  different decomposition than the oracle's (i,j) page loop), the OOB-page
//  and seq_len-truncation contracts, and the null-arg / empty no-op edges.
// ===========================================================================
namespace {

// Independent reference: iterate (b, t) with t outer and i=t/block, j=t%block,
// skipping individual tokens at t>=seq_len (continue, not a page break) and
// OOB pages. Different control structure than dsa_topk_logits_cpu's
// (b, i, j) page loop with a break on truncation -- same result.
void topk_ref(int batch_size, int num_heads, int head_dim, int block,
              int max_table_len, int num_blocks,
              const std::vector<float>& q, const std::vector<float>& kv,
              const std::vector<float>& k_scale, const std::vector<float>& gate,
              const std::vector<int32_t>& seq_lens,
              const std::vector<int32_t>& page_table,
              std::vector<float>& out) {  // [bs, max_table_len*block], ZEROED
  for (int b = 0; b < batch_size; ++b) {
    const int seq_len = seq_lens[b];
    const int max_t = max_table_len * block;
    for (int t = 0; t < max_t; ++t) {
      if (t >= seq_len) continue;             // truncate at seq_len (NOT a break)
      const int i = t / block, j = t % block;
      const int32_t page = page_table[(size_t)b * max_table_len + i];
      if (page < 0 || page >= num_blocks) continue;
      float acc = 0.0f;
      for (int h = 0; h < num_heads; ++h) {
        const float* qh = q.data() + (((size_t)b * num_heads + h) * head_dim);
        const float* kj = kv.data() + (((size_t)page * block + j) * head_dim);
        float dot = 0.0f;
        for (int d = 0; d < head_dim; ++d) dot += qh[d] * kj[d];
        acc += std::fmax(dot, 0.0f) * gate[(size_t)b * num_heads + h];
      }
      out[(size_t)b * max_table_len * block + t] =
          k_scale[(size_t)page * block + j] * acc;
    }
  }
}

}  // namespace

