  struct Cfg { int batch, H, D, block, max_table_len, num_blocks; };
  const Cfg cfgs[] = {
      {1, 2, 8, 4, 16, 16},     // H=2 small D
      {1, 4, 16, 8, 8, 8},      // H=4
      {2, 1, 8, 4, 8, 8},       // batch=2, H=1
      {1, 2, 128, 64, 4, 4},    // GLM-5.3-ish: D=128, block=64
      {1, 1, 2, 2, 4, 4},       // tiny
  };
  std::mt19937 rng(98765);
  auto rf = [&]() { return static_cast<float>(rng() % 2000) / 1000.0f - 1.0f; };
  for (const auto& c : cfgs) {
    std::vector<float> q((size_t)c.batch * c.H * c.D);
    std::vector<float> kv((size_t)c.num_blocks * c.block * c.D);
    std::vector<float> k_scale((size_t)c.num_blocks * c.block);
    std::vector<float> gate((size_t)c.batch * c.H);
    std::vector<int32_t> seq_lens(c.batch);
    std::vector<int32_t> pt((size_t)c.batch * c.max_table_len);
    for (auto& x : q) x = rf();
    for (auto& x : kv) x = rf();
    for (auto& x : k_scale) x = rf();
    for (auto& x : gate) x = rf();
    for (int b = 0; b < c.batch; ++b)
      seq_lens[b] = static_cast<int>(rng() % (c.max_table_len * c.block + 1));
    for (int b = 0; b < c.batch; ++b)
      for (int i = 0; i < c.max_table_len; ++i)
        pt[(size_t)b * c.max_table_len + i] =
            (i % 10 == 9) ? -1 : static_cast<int32_t>(rng() % c.num_blocks);
    const size_t nout = (size_t)c.batch * c.max_table_len * c.block;
    std::vector<float> got(nout, 0), ref(nout, 0);
    dsa_topk_logits_cpu(c.batch, c.H, c.D, c.block, c.max_table_len,
                        c.num_blocks, q.data(), kv.data(), k_scale.data(),
                        gate.data(), seq_lens.data(), pt.data(), got.data());
    topk_ref(c.batch, c.H, c.D, c.block, c.max_table_len, c.num_blocks,
             q, kv, k_scale, gate, seq_lens, pt, ref);
    float maxd = 0;
    for (size_t i = 0; i < nout; ++i)
      maxd = std::max(maxd, std::fabs(got[i] - ref[i]));
    EXPECT_NEAR(maxd, 0.0f, 1e-5f);
  }
}

