// ---------------------------------------------------------------------------
//  DSA paged-MQA gated top-k logits (issue #51): CPU oracle coverage.
//  Hand-checked cases exercise the formula (multi-head gate weighting + ReLU
//  masking), the in-page seq_len truncation (left-unwritten contract), and
//  the out-of-range page guard. The cross-check runs an independent
//  reference (t-outer iteration with `continue`, vs the oracle's (i,j)
//  decomposition with `break`) over randomized GLM-5.3-ish shapes.
// ---------------------------------------------------------------------------
namespace {

void topk_ref(int batch_size, int num_heads, int head_dim, int block,
              int max_table_len, int num_blocks,
              const std::vector<float>& q,   // [bs, H, D]
              const std::vector<float>& kv,  // [num_blocks, block, D]
              const std::vector<float>& k_scale,  // [num_blocks, block]
              const std::vector<float>& gate,     // [bs, H]
              const std::vector<int32_t>& seq_lens,
              const std::vector<int32_t>& page_table,
              std::vector<float>& out) {  // [bs, max_table_len*block], ZEROED
  for (int b = 0; b < batch_size; ++b) {
    const int seq_len = seq_lens[b];
    const int max_t = max_table_len * block;
    for (int t = 0; t < max_t; ++t) {
      if (t >= seq_len) continue;  // truncate at seq_len (NOT a page break)
      const int i = t / block, j = t % block;
      const int32_t page = page_table[(size_t)b * max_table_len + i];
      if (page < 0 || page >= num_blocks) continue;
      float acc = 0.0f;
      for (int h = 0; h < num_heads; ++h) {
        const float* qh = q.data() + (((size_t)b * num_heads + h) * head_dim);
        const float* kj = kv.data() + (((size_t)page * block + j) * head_dim);
        float dot = 0.0f;
        for (int d = 0; d < head_dim; ++d) dot += qh[d] * kj[d];
        acc += std::fmax(dot, 0.0f) * gate[(size_t)b * num_heads + h];
      }
      out[(size_t)b * max_table_len * block + t] =
          k_scale[(size_t)page * block + j] * acc;
    }
  }
}

}  // namespace

// q=[1,1], one page of [[1,0],[0,1]], scales [2,3], gate [1].
//   out[0] = 2 * (max(0,1)*1) = 2 ;  out[1] = 3 * (max(0,1)*1) = 3
TEST(DsaTopk, HandCheckedSingleHead) {
  std::vector<float> q = {1, 1};
  std::vector<float> kv = {1, 0,  0, 1};
  std::vector<float> k_scale = {2, 3};
  std::vector<float> gate = {1};
  std::vector<int32_t> seq_lens = {2};
  std::vector<int32_t> page_table = {0};
  std::vector<float> out(2, 0);
  dsa_topk_logits_cpu(1, 1, 2, 2, 1, 1, q.data(), kv.data(), k_scale.data(),
                      gate.data(), seq_lens.data(), page_table.data(),
                      out.data());
  EXPECT_NEAR(out[0], 2.0f, 1e-6);
  EXPECT_NEAR(out[1], 3.0f, 1e-6);
}

// H=2 with per-head gate weights [2,3]; both heads' negative dots ReLU-mask.
//   page0 key=[1,-1]: H0 dot= 1 -> 2; H1 dot=-1 -> 0   => out[0]=2
//   page1 key=[-2,2]: H0 dot=-2 -> 0; H1 dot= 2 -> 6   => out[1]=6
TEST(DsaTopk, HandCheckedMultiHeadGateAndRelu) {
  std::vector<float> q = {1, 0,  0, 1};        // H0=[1,0], H1=[0,1]
  std::vector<float> kv = {1, -1,  -2, 2};     // page0=[1,-1], page1=[-2,2]
  std::vector<float> k_scale = {1, 1};
  std::vector<float> gate = {2, 3};
  std::vector<int32_t> seq_lens = {2};
  std::vector<int32_t> page_table = {0, 1};
  std::vector<float> out(2, 0);
  dsa_topk_logits_cpu(1, 2, 2, 1, 2, 2, q.data(), kv.data(), k_scale.data(),
                      gate.data(), seq_lens.data(), page_table.data(),
                      out.data());
  EXPECT_NEAR(out[0], 2.0f, 1e-6);
  EXPECT_NEAR(out[1], 6.0f, 1e-6);
}

