// Cross-check against the independent reference across GLM-5.3-ish and tiny
// shapes, with randomized Q/K/scales/gate and ~10% of pages masked to -1.
TEST(DsaTopk, MatchesReference) {
  struct Cfg { int batch, H, D, block, max_table_len, num_blocks; };
  const Cfg cfgs[] = {
      {1, 2, 8, 4, 16, 16},
      {1, 4, 16, 8, 32, 32},
      {2, 1, 8, 4, 16, 16},
      {1, 2, 128, 64, 8, 8},   // GLM-5.3 layout (D=128, block=64), small H
      {1, 1, 2, 2, 4, 4},
  };
  std::mt19937 rng(98765);
  auto rf = [&]() { return static_cast<float>(rng() % 2000) / 1000.0f - 1.0f; };
  for (const auto& c : cfgs) {
    const int W = c.D;                          // no rope tail on this path
    const int max_t = c.max_table_len * c.block;
    std::vector<float> q((size_t)c.batch * c.H * c.D);
    std::vector<float> kv((size_t)c.num_blocks * c.block * c.D);
    std::vector<float> k_scale((size_t)c.num_blocks * c.block);
    std::vector<float> gate((size_t)c.batch * c.H);
    std::vector<int32_t> seq_lens(c.batch);
    std::vector<int32_t> page_table((size_t)c.batch * c.max_table_len);
    for (auto& x : q) x = rf();
    for (auto& x : kv) x = rf();
    for (auto& x : k_scale) x = 0.5f + (rng() % 1000) / 1000.0f;  // [0.5,1.5)
    for (auto& x : gate) x = rf();
    for (auto& x : seq_lens) x = (int)(rng() % (unsigned)(max_t + 1));
    for (int b = 0; b < c.batch; ++b)
      for (int i = 0; i < c.max_table_len; ++i)
        page_table[(size_t)b * c.max_table_len + i] =
            (i % 10 == 9) ? -1 : (int32_t)(rng() % (unsigned)c.num_blocks);

    std::vector<float> out((size_t)c.batch * max_t, 0);
    std::vector<float> rout((size_t)c.batch * max_t, 0);
    dsa_topk_logits_cpu(c.batch, c.H, c.D, c.block, c.max_table_len,
                        c.num_blocks, q.data(), kv.data(), k_scale.data(),
                        gate.data(), seq_lens.data(), page_table.data(),
                        out.data());
    topk_ref(c.batch, c.H, c.D, c.block, c.max_table_len, c.num_blocks, q,
             kv, k_scale, gate, seq_lens, page_table, rout);

    float maxd = 0;
    for (size_t i = 0; i < out.size(); ++i)
      maxd = std::max(maxd, std::fabs(out[i] - rout[i]));
    EXPECT_NEAR(maxd, 0.0f, 1e-4f);
  }
}

