TEST(DsaTopk, HandCheckedSingleHead) {
  std::vector<float> q = {1, 1};
  std::vector<float> kv = {1, 0, 0, 1};        // [1 block][2 tokens][2]
  std::vector<float> k_scale = {2, 3};          // [1 block][2 tokens]
