===dsa.hpp: the canonical CPU formula docstring (my pointers point HERE) lines 92-145===
// ---------------------------------------------------------------------------
//  DSA paged-MQA gated top-k logits (issue #51, the kpool>1 indexer path).
//
//  The INDEXER computes, per query token and paged KV tile, a gated logit
//  that the subsequent top-k selects over (GLM-5.3-Flash `index_n_heads=32`,
//  `index_head_dim=128`, block_size=64 hardcoded in deep_gemm). The tilelang
//  kernel JIT-compiles on gfx942 but the launched kernel NEVER returns for
//  num_heads in {32,64}; deep_gemm.fp8_paged_mqa_logits is CUDA-only. This is
//  the portable replacement — the FIRST stage (kpool logits) that feeds the
//  PR #52 sparse-MLA forward.
//
//  Computation (per batch b, KV token t = i*block + j; i in
//  [0, ceildiv(seq_len[b], block)), j in [0, block)):
//
//    out[b, t] = k_scale[ page[b,i], j ]
//              * Sum_h ( max(0, Sum_d Q[b,h,d] * K[ page[b,i], j,d ] )
//                        * gate[b, h] )
//
//  Tokens t >= seq_len[b] are LEFT UNWRITTEN — exactly as the tilelang path
//  leaves them with `clean_logits=False` (the wrapper allocates with
//  `new_empty`, i.e. UNINITIALISED; sglang's `topk_from_pooled_history_logits`
//  masks invalid positions via `group_lengths`/`topk_offsets`/`seq_lens` BEFORE
//  the top-k, so unwritten/zero/garbage are all excluded). The HIP caller and
//  the unit test ZERO the output first (strictly safer than the original's
//  `new_empty`, harmless under the same masking).
//
//  Tensors (kv_group == 1; `page_size = block = 64`, `head_dim = 128`):
//
//    q        : [bs, H, D]         fp8 e4m3fnuz (device) / fp32 (oracle)
//    kv       : [num_blocks, block, D]                 fp8 e4m3fnuz / fp32
//    k_scale  : [num_blocks, block]                    fp32 (per-token
//               scale, packed in the trailing `block*4` bytes of each KV
//               block on the device path; passed separately on the CPU path)
//    gate     : [bs, H]                               fp32 (the indexer's
//               `_get_logits_head_gate` weight, after `.squeeze(2)`)
//    seq_lens : [bs]                                  int32 (the POOLED valid
//               KV count per batch — `pool_seqlens` in sglang)
//    page_table: [bs, max_table_len]                  int32 (the POOLED page
//               table — `pool_block_tables` in sglang; page_table[b,i] indexes
//               the `num_blocks` dim of kv/k_scale)
//    out      : [bs, max_seq_len]                     fp32
//               (max_seq_len = max_table_len * block; ZERO the output first)
//
//  `split_kv` is a PERFORMANCE knob only — the grouped logit is
//  grouping-independent (mirrors the forward's block_I/inner_iter), so any
//  positive split_kv yields the same top-k. The tilelang reference uses
//  `split_kv = max(1, min(max_seq_len // block, NUM_CU // batch_size))`
//  with `NUM_CU = 256` (MI300A); the HIP caller replicates this.
void dsa_topk_logits_cpu(int batch_size, int num_heads, int head_dim, int block,
                         int max_table_len, int num_blocks,
                         const float* q, const float* kv,
                         const float* k_scale, const float* gate,
                         const int32_t* seq_lens, const int32_t* page_table,
                         float* out);

===moe_device.hip: final fp8e4m3fnuz_to_f32 comment (Blocker 1 + P4)===
// OCP FP8 e4m3fnuz -> fp32 (GLM-5.3-Flash on MI300A stores its KV cache and
// the DSA-indexer query as torch.float8_e4m3fnuz). e4m3fnuz layout: 1 sign |
// 4 exponent (BIAS 8) | 3 mantissa, NO infinity, NaN at 0x7F (exp=15,
// mant=7), max finite 0x7E = 2^(15-8)*(1+6/8) = 224.0, and NO negative zero
// (0x00 AND 0x80 both decode to +0.0). Subnormals (exp==0, mant!=0) scale
// as m * 2^(1-bias) = m * 2^-7. Mirrors fp4nib_to_f32bits / bf16_to_f32:
// pure IEEE bit manipulation, no FP8 header. __host__ as well as __device__
// so the GPU cross-check harness (meta/benchmarks/test_dsa_topk_correct.hip)
// can dequant the fp8 source on the host -- the value BOTH the CPU oracle
// (dsa_topk_logits_cpu, fed the recovered fp32) and the device kernel
// (dsa.hip, dequanting on load) see. This MUST match
// torch.tensor(b, dtype=torch.uint8).view(torch.float8_e4m3fnuz).to(torch.float32)
// exactly; the harness cross-checks the two dequant paths.
__host__ __device__ __forceinline__ float fp8e4m3fnuz_to_f32(uint8_t b) {
  const uint32_t s = static_cast<uint32_t>(b >> 7) & 1u;     // sign
  const uint32_t e = static_cast<uint32_t>(b >> 3) & 0xFu;   // exponent (bias 8)
  const uint32_t m = static_cast<uint32_t>(b) & 0x7u;        // mantissa (3)
  if ((b & 0x7Fu) == 0u) return 0.0f;                        // +0 (0x00 AND 0x80)
  float f;
  if (e == 15u && m == 7u) {                                 // 0x7F = NaN -> qNaN
    const uint32_t qnan = 0x7fc00000u;
    __builtin_memcpy(&f, &qnan, sizeof(f));
  } else if (e == 0u) {                                      // subnormal: m*2^-7
    const float v = static_cast<float>(m) * 0x1p-7f;         // m*2^(1-8), exact
    f = s ? -v : v;
  } else {                                                   // normal: 2^(e-8)*(1+m/8)
    const uint32_t bits = (s << 31) | ((e + 119u) << 23) | (m << 20);
    __builtin_memcpy(&f, &bits, sizeof(f));
  }
  return f;
}

// ======================================================================
//  K16 bf16 MFMA (device-only, inline asm)
//  NOTE: Uses generic "v" constraints (no hardcoded VGPRs).

===dsa.cpp: final dsa_topk_logits_cpu (Blocker 2 comment + P1 guards/mask)===
// ---------------------------------------------------------------------------
//  DSA paged-MQA gated top-k logits — CPU reference (oracle), issue #51.
//  See dsa.hpp for the layout and the gated-logit formula. Pure fp32, single
//  pass (no softmax — the topk IS the softmax-free scoring stage). The HIP
//  kernel (dsa.hip) is cross-checked against this by
//  meta/benchmarks/test_dsa_topk_correct.hip: it dequants the fp8 e4m3fnuz
//  source on the host (via fp8e4m3fnuz_to_f32, the same helper the kernel
//  uses on load) and feeds the recovered fp32 to this oracle; the Python
//  caller dequants via torch.float8_e4m3fnuz. The host tests
//  (tests/kernels/attn/test_dsa.cpp, DsaTopk*) cover the oracle directly.
//
//  Tokens t >= seq_len[b] are LEFT UNWRITTEN — the caller ZEROES the output
//  first (strictly safer than the tilelang wrapper's `new_empty`, harmless
//  under sglang's `topk_from_pooled_history_logits` masking).
// ---------------------------------------------------------------------------
void dsa_topk_logits_cpu(int batch_size, int num_heads, int head_dim, int block,
                         int max_table_len, int num_blocks,
                         const float* q, const float* kv,
                         const float* k_scale, const float* gate,
                         const int32_t* seq_lens, const int32_t* page_table,
                         float* out) {
  VK_EXPECTS(batch_size >= 0 && num_heads > 0 && head_dim > 0 && block > 0,
             "batch_size >= 0 and num_heads/head_dim/block > 0 required");
  VK_EXPECTS(max_table_len >= 0 && num_blocks >= 0,
             "max_table_len >= 0 and num_blocks >= 0 required");
  // With work to do, every pointer is required (mirrors dsa_sparse_fwd_cpu).
  VK_EXPECTS(batch_size == 0 || max_table_len == 0 || q != nullptr,
             "q must not be null");
  VK_EXPECTS(batch_size == 0 || max_table_len == 0 || kv != nullptr,
             "kv must not be null");
  VK_EXPECTS(batch_size == 0 || max_table_len == 0 || k_scale != nullptr,
             "k_scale must not be null");
  VK_EXPECTS(batch_size == 0 || max_table_len == 0 || gate != nullptr,
             "gate must not be null");
  VK_EXPECTS(batch_size == 0 || max_table_len == 0 || seq_lens != nullptr,
             "seq_lens must not be null");
  VK_EXPECTS(batch_size == 0 || max_table_len == 0 || page_table != nullptr,
             "page_table must not be null");
  VK_EXPECTS(batch_size == 0 || max_table_len == 0 || out != nullptr,
             "out must not be null");
  if (batch_size == 0 || max_table_len == 0) return;  // nothing to write
  // num_blocks == 0: every page is out of range -> output stays zeroed
  // (the OOB-page guard below mirrors dsa_sparse_fwd_cpu's idx<S_kv mask).

  for (int b = 0; b < batch_size; ++b) {
    const int seq_len = seq_lens[b];
    const int np_total = (seq_len + block - 1) / block;  // pages with content
    const int32_t* pt_b = page_table + (size_t)b * max_table_len;
    const float* qb = q + (size_t)b * num_heads * head_dim;
